async fn replace_declarations(
    tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
    declarations: &[LoadDeclaration],
) -> Result<(), EntityIngestionError> {
    for declaration in declarations {
        let stored_member_id = sqlx::query!(
            "SELECT id FROM exposed.members WHERE parliament_member_id = $1",
            i32::try_from(declaration.member_id.value()).map_err(db_error)?
        )
        .fetch_optional(&mut **tx)
        .await
        .map_err(db_error)?
        .ok_or_else(|| {
            data_error(format!(
                "member {} must be loaded before declarations",
                declaration.member_id
            ))
        })?
        .id;
        let inserted = sqlx::query!(
                "INSERT INTO exposed.declarations (source_declaration_id, member_id, category_id, category_name, fetched_at, registration_date) VALUES ($1, $2, $3, $4, $5, $6) ON CONFLICT (source_declaration_id) DO UPDATE SET member_id = EXCLUDED.member_id, category_id = EXCLUDED.category_id, category_name = EXCLUDED.category_name, fetched_at = EXCLUDED.fetched_at, registration_date = EXCLUDED.registration_date WHERE exposed.declarations.fetched_at <= EXCLUDED.fetched_at RETURNING source_declaration_id",
                i32::try_from(declaration.source_declaration_id.value()).map_err(db_error)?,
                stored_member_id,
                i32::try_from(declaration.category_id).map_err(db_error)?,
                declaration.category_name,
                sql_timestamp(declaration.fetched_at)?,
                declaration.registration_date.map(|date| date.and_hms_opt(0, 0, 0).expect("midnight is valid").and_utc()).map(sql_timestamp).transpose()?
            ).fetch_optional(&mut **tx).await.map_err(db_error)?;
        if inserted.is_none() {
            return Err(data_error(format!(
                "declaration {} is already loaded at a newer capture time",
                declaration.source_declaration_id
            )));
        }
        sqlx::query!(
            "DELETE FROM exposed.funding_entries WHERE source_declaration_id = $1",
            i32::try_from(declaration.source_declaration_id.value()).map_err(db_error)?
        )
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    }
    Ok(())
}

async fn replace_funders<'a>(
    tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
    funders: &'a [LoadFunder],
) -> Result<BTreeMap<&'a str, uuid::Uuid>, EntityIngestionError> {
    let mut funder_ids = BTreeMap::new();
    for funder in funders {
        let id = sqlx::query!(
                "INSERT INTO exposed.funders (funder_name, funder_kind, company_number, resolution_identity_id) VALUES ($1, $2, $3, $4) ON CONFLICT (resolution_identity_id) DO UPDATE SET funder_name = EXCLUDED.funder_name, funder_kind = EXCLUDED.funder_kind, company_number = EXCLUDED.company_number RETURNING id",
                funder.name,
                funder.kind,
                funder.company_number,
                funder.identity_id
            ).fetch_one(&mut **tx).await.map_err(db_error)?.id;
        funder_ids.insert(funder.identity_id.as_str(), id);
        sqlx::query!(
            "DELETE FROM exposed.funder_aliases WHERE funder_id = $1",
            id
        )
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
        for alias in funder.aliases.iter().chain(std::iter::once(&funder.name)) {
            sqlx::query!(
                    "INSERT INTO exposed.funder_aliases (funder_id, funder_alias) VALUES ($1, $2) ON CONFLICT (funder_id, funder_alias) DO NOTHING",
                    id,
                    alias
                )
                .execute(&mut **tx)
                .await
                .map_err(db_error)?;
        }
    }
    Ok(funder_ids)
}

//! Atomic projection of the pipeline's grouping policy into stored membership and evidence.

use sqlx::{Postgres, Transaction};

use crate::domain::models::{
    entity_ingestion::EntityIngestionError,
    funder::FunderId,
    funder_grouping::{GroupingFunder, build_funder_groups},
};

#[cfg(test)]
use super::ExposedDatabase;

#[cfg(test)]
impl ExposedDatabase {
    /// Rebuilds grouping for every persisted identity without replaying ingestion artifacts.
    ///
    /// # Errors
    /// Returns database or grouping-policy errors. A failed refresh preserves the previous projection.
    pub async fn refresh_funder_groups(&self) -> Result<usize, EntityIngestionError> {
        let mut tx = self.pool().begin().await.map_err(db_error)?;
        lock_declaration_loader(&mut tx).await?;
        let count = replace_funder_groups(&mut tx).await?;
        tx.commit().await.map_err(db_error)?;
        Ok(count)
    }
}

pub(super) async fn lock_declaration_loader(
    tx: &mut Transaction<'_, Postgres>,
) -> Result<(), EntityIngestionError> {
    sqlx::query!("SELECT pg_advisory_xact_lock(hashtext('exposed.declaration-loader'))")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    Ok(())
}

pub(super) async fn replace_funder_groups(
    tx: &mut Transaction<'_, Postgres>,
) -> Result<usize, EntityIngestionError> {
    let rows = sqlx::query!("SELECT id, funder_name FROM exposed.funders ORDER BY id")
        .fetch_all(&mut **tx)
        .await
        .map_err(db_error)?;
    let aliases = sqlx::query!("SELECT funder_id, funder_alias FROM exposed.funder_aliases ORDER BY funder_id, funder_alias")
        .fetch_all(&mut **tx).await.map_err(db_error)?;
    let mut by_id = std::collections::BTreeMap::<_, Vec<_>>::new();
    for alias in aliases {
        by_id
            .entry(alias.funder_id)
            .or_default()
            .push(alias.funder_alias);
    }
    let funders: Vec<_> = rows
        .into_iter()
        .map(|row| GroupingFunder {
            id: FunderId::new(row.id),
            name: row.funder_name,
            aliases: by_id.remove(&row.id).unwrap_or_default(),
        })
        .collect();
    let groups = build_funder_groups(&funders).map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_group_names")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_alias_links")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_family_links")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_alias_groups")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    for (id, group) in &groups.memberships {
        sqlx::query!(
            "INSERT INTO exposed.funder_alias_groups (funder_id, group_id) VALUES ($1, $2)",
            id.value(),
            group.value()
        )
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    }
    for name in groups.preferred_names {
        sqlx::query!("INSERT INTO exposed.funder_group_names (group_id, preferred_name, family_key) VALUES ($1, $2, $3)", name.group_id.value(), name.preferred_name.as_str(), name.family_key)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    for link in groups.alias_links {
        sqlx::query!("INSERT INTO exposed.funder_alias_links (left_funder_id, right_funder_id, normalized_alias, left_alias, right_alias) VALUES ($1, $2, $3, $4, $5)", link.left_funder_id.value(), link.right_funder_id.value(), link.normalized_alias, link.left_alias, link.right_alias)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    for link in groups.family_links {
        sqlx::query!("INSERT INTO exposed.funder_family_links (left_funder_id, right_funder_id, family_key, left_name, right_name) VALUES ($1, $2, $3, $4, $5)", link.left_funder_id.value(), link.right_funder_id.value(), link.family_key, link.left_name, link.right_name)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    Ok(groups.memberships.len())
}

