CONSTANT Size

VARIABLE counter

TypeOK == counter \in 0..Size

Init == counter = 0

Inc == /\ counter < Size

/\ counter' = counter + 1

Dec == /\ counter > 0

/\ counter' = counter - 1

Next == Inc / Dec

