        observations: observations.into_iter().map(|o| (o.funder_id.clone(), o)).collect(),
        payments: payments.into_iter().map(|p| (p.funding_entry_id.clone(), p)).collect(),
        digests: Default::default(),
    }
}

#[kani::proof]
#[kani::unwind(40)]
fn parent_eligibility_and_flag_gate() {
    let same_member: bool = kani::any();
    let immediate_parent: bool = kani::any();
    let root: bool = kani::any();
    let payer_role: bool = kani::any();
    let flag: u8 = kani::any();
    kani::assume(flag < 3);
    let mut child = proof_payment(false);
    child.parent_declaration_id = Some(proof_payment(true).declaration_id);
    child.is_ultimate_payer_different = [None, Some(false), Some(true)][usize::from(flag)];
    let mut parent = proof_payment(true);
    if !same_member {
        parent.member_id = MemberId(2);
        parent.funding_entry_id = FundingEntryId("2/1/1/funding/0".into());
    }
    if !immediate_parent {
        parent.declaration_id = DeclarationId(std::num::NonZeroU32::new(3).unwrap());
        parent.funding_entry_id = FundingEntryId(if same_member { "1/3/1/funding/0" } else { "2/3/1/funding/0" }.into());
    }
    let role = if payer_role { FunderRole::Payer } else { FunderRole::Donor };
    let mut candidate = proof_role("p", &parent, role);
    if !root {
        candidate.source_pointer = "/versions/0/fields/0/values/0".into();
    }
    // IDs are opaque in this extracted core; the production loader checks their spelling.
    if payer_role {
        parent.payer_funder_id = Some(candidate.funder_id.clone());
    } else {
        parent.donor_funder_id = Some(candidate.funder_id.clone());
    }
    let id = candidate.funder_id.clone();
    let input = proof_input(vec![candidate], vec![parent, child.clone()]);
    let decision = attribute(&input, &child).decision;
    let correct = match flag {
        0 => matches!(decision, AttributionDecision::Unavailable { unavailable_reason: UnavailableReason::NoSupportedAttribution }),
        2 => matches!(decision, AttributionDecision::Unavailable { unavailable_reason: UnavailableReason::DifferentUltimatePayerUnnamed }),
        _ if same_member && immediate_parent && root && payer_role => matches!(decision,
            AttributionDecision::Selected { selected_funder_id, attribution_basis: AttributionBasis::ParentPayer, selected_parent_declaration_id }
            if selected_funder_id == id && selected_parent_declaration_id == child.parent_declaration_id),
        _ => matches!(decision, AttributionDecision::Unavailable { unavailable_reason: UnavailableReason::ParentEvidenceUnavailable }),
    };
    assert!(correct, "parent selection requires false flag and same-member immediate-parent root payer");
}

#[kani::proof]
#[kani::unwind(40)]
fn explicit_ultimate_precedence_and_withholding() {
    let usable: bool = kani::any();
    let flag: u8 = kani::any();
    kani::assume(flag < 3);
    let mut child = proof_payment(false);
