#[kani::proof]
fn explicit_type_controls_company_identifier() {
    let kinds = [None, Some("company"), Some(" COMPANY "), Some("person"), Some("organisation"), Some("mystery"), Some("")];
    let choice: usize = kani::any();
    kani::assume(choice < kinds.len());
    let mut row = super::observation("a");
    row.donor_kind = kinds[choice].map(str::to_owned);
    row.donor_company_number = Some("00000001".into());
    assert_eq!(company(&row).as_deref(), (choice < 3).then_some("00000001"), "explicit non-company type blocks a company identifier");
}

#[kani::proof]
fn company_identifier_normalization() {
    let cases = [
        (None, None),
        (Some("00000001"), Some("00000001")),
        (Some(" ab123456 \t"), Some("AB123456")),
        (Some("ABCDEFGH"), None),
        (Some("1234567"), None),
        (Some("123456789"), None),
        (Some("00000!01"), None),
    ];
    let choice: usize = kani::any();
    kani::assume(choice < cases.len());
    let mut row = super::observation("a");
    row.donor_company_number = cases[choice].0.map(str::to_owned);
    assert_eq!(company(&row).as_deref(), cases[choice].1, "company identifier follows captured-source format");
}

#[kani::proof]
fn distinct_companies_stay_separate() {
    let mut first = super::observation("a");
    first.donor_company_number = Some("00000001".into());
    let middle = super::observation("b");
    let mut last = super::observation("c");
    last.donor_company_number = Some("00000002".into());
    let mask: u8 = kani::any();
    kani::assume(mask < 8);
    let rows = run_graph(vec![first, middle, last], mask);
    assert_eq!(rows[0].identity_id.as_deref(), Some("source-reported:companies-house:00000001"), "first company keeps its own identifier");
    assert_eq!(rows[2].identity_id.as_deref(), Some("source-reported:companies-house:00000002"), "conflicting company retains its distinct identifier");
    if mask & 1 != 0 && mask & 4 != 0 {
        assert_eq!(rows[1].identity_id.as_deref(), Some("run-local:proof:b"), "ambiguous observation does not choose either company");
    }
}

#[kani::proof]
fn company_identifier_precedes_name_fallback() {
    let named: bool = kani::any();
    let mut row = super::observation("a");
    row.name_normalized = named.then(|| "a".into());
    row.donor_company_number = Some("00000001".into());
    let rows = run_graph(vec![row], 0);
    assert_eq!(rows[0].identity_id.as_deref(), Some("source-reported:companies-house:00000001"), "accepted company identifier precedes name fallback");
    assert!(matches!(rows[0].identity_basis, IdentityBasis::SourceReportedCompany), "captured company evidence retains its source basis");
}

#[kani::proof]
fn constant_company_outcome() {
    let mut row = super::observation("a");
    row.donor_company_number = Some("00000001".into());
    let rows = run_graph(vec![row], 0);
    assert_eq!(rows[0].identity_id.as_deref(), Some("source-reported:companies-house:00000001"));
}

#[kani::proof]
fn numeric_company_identifiers_are_preserved() {
    let mut bytes: [u8; 8] = kani::any();
    for byte in &mut bytes {
        kani::assume(*byte < 10);
        *byte += b'0';
    }
    let identifier = String::from_utf8(bytes.to_vec()).unwrap();
    let mut row = super::observation("a");
    row.donor_company_number = Some(identifier.clone());
    assert_eq!(company(&row).as_deref(), Some(identifier.as_str()), "all eight-digit company identifiers are preserved");
}

