#[test]
fn nested_type_and_identifier_fields_remain_in_their_own_scope() {
    for flags in 0..16_u8 {
        for depth in 1..=2 {
            for donors in [false, true] {
                let mut child = vec![
                    json!({"name": if donors { "Name" } else { "DonorName" }, "value": "Child"}),
                    json!({"name": "Value", "value": "1"}),
                ];
                if flags & 4 != 0 {
                    child.push(json!({"name": "DonorStatus", "value": "Person"}));
                }
                if flags & 8 != 0 {
                    child.push(json!({"name": "DonorCompanyIdentifier", "value": "00000002"}));
                }
                let mut nested =
                    json!({"name": if donors { "Donors" } else { "Payments" }, "values": [child]});
                if depth == 2 {
                    nested = json!({"name": "Intermediate", "values": [[
                        {"name": "DonorStatus", "value": "Organisation"},
                        {"name": "DonorCompanyIdentifier", "value": "00000003"},
                        nested
                    ]]});
                }
                let mut fields = vec![json!({"name": "PaymentType", "value": "Monetary"}), nested];
                if flags & 1 != 0 {
                    fields.push(json!({"name": "DonorStatus", "value": "Company"}));
                }
                if flags & 2 != 0 {
                    fields.push(json!({"name": "DonorCompanyIdentifier", "value": "00000001"}));
                }
                let fields: Vec<SourceField> = serde_json::from_value(json!(fields)).unwrap();
                let mut entries = Vec::new();
                let mut pointers = Vec::new();
                funding_entries(&fields, "/versions/0/fields", &mut entries, &mut pointers)
                    .unwrap();
                assert_eq!(entries.len(), 2);
                assert_eq!(pointers.len(), 2);
                assert_ne!(pointers[0], pointers[1]);
                assert_eq!(
                    entries[0].funder_kind(),
                    (flags & 1 != 0).then_some("Company"),
                    "parent type stays local"
                );
                assert_eq!(
                    entries[0].company_number(),
                    (flags & 2 != 0).then_some("00000001"),
                    "parent identifier stays local"
                );
                assert_eq!(
                    entries[1].funder_kind(),
                    (flags & 4 != 0).then_some("Person"),
                    "nested type stays local and missing type is not inherited"
                );
                assert_eq!(
                    entries[1].company_number(),
                    (flags & 8 != 0).then_some("00000002"),
                    "nested identifier stays local and missing identifier is not inherited"
                );
            }
        }
    }
}

use quote::ToTokens;
use std::{collections::BTreeSet, env, fs, path::PathBuf};
use syn::{Attribute, Item, Path, punctuated::Punctuated, visit_mut::VisitMut};

struct ProofAttributes;

fn retain_attributes(attributes: &mut Vec<Attribute>) {
    attributes.retain_mut(|attribute| {
        if attribute.path().is_ident("derive") {
            let mut derives = attribute
                .parse_args_with(Punctuated::<Path, syn::Token![,]>::parse_terminated)
                .expect("parse production derives");
            derives = derives
                .into_iter()
                .filter(|path| {
                    matches!(
                        path.segments.last().unwrap().ident.to_string().as_str(),
                        "Clone"
                            | "Copy"
                            | "Debug"
                            | "Default"
                            | "PartialEq"
                            | "Eq"
                            | "PartialOrd"
                            | "Ord"
                            | "Hash"
                    )
                })
                .collect();
            if derives.is_empty() {
                return false;
            }
            *attribute = syn::parse_quote!(#[derive(#derives)]);
            return true;
        }
        if attribute.path().is_ident("default") {
            return true;
        }
        assert!(
            ["doc", "serde", "strum", "error", "from", "cfg_attr"]
                .iter()
                .any(|name| attribute.path().is_ident(name)),
            "unreviewed attribute on a canonical proof type: {}",
            attribute.to_token_stream()
        );
        false
    });
}

impl VisitMut for ProofAttributes {
    fn visit_visibility_mut(&mut self, visibility: &mut syn::Visibility) {
        if let syn::Visibility::Restricted(restricted) = visibility
            && restricted.path.is_ident("super")
        {
            *visibility = syn::parse_quote!(pub(crate));
        }
    }

    fn visit_item_struct_mut(&mut self, item: &mut syn::ItemStruct) {
        retain_attributes(&mut item.attrs);
        syn::visit_mut::visit_item_struct_mut(self, item);
    }

    fn visit_item_enum_mut(&mut self, item: &mut syn::ItemEnum) {
        retain_attributes(&mut item.attrs);
        syn::visit_mut::visit_item_enum_mut(self, item);
    }

    fn visit_field_mut(&mut self, field: &mut syn::Field) {
        retain_attributes(&mut field.attrs);
        syn::visit_mut::visit_field_mut(self, field);
    }

    fn visit_variant_mut(&mut self, variant: &mut syn::Variant) {
        retain_attributes(&mut variant.attrs);
        syn::visit_mut::visit_variant_mut(self, variant);
    }
}

