                            | "Copy"
                            | "Debug"
                            | "Default"
                            | "PartialEq"
                            | "Eq"
                            | "PartialOrd"
                            | "Ord"
                            | "Hash"
                    )
                })
                .collect();
            if derives.is_empty() {
                return false;
